content.text:
.inventory{display:none;position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:min(360px,85vw);padding:15px;pointer-events:auto}
.invgrid{display:grid;grid-template-columns:repeat(5,1fr);gap:7px;margin:12px 0}
.invslot{height:54px;background:#111713;border:1px solid #565641;display:grid;place-items:center;font-size:21px;position:relative}
.invnote{font-size:9px;color:#b9b399;line-height:1.6}
.damage{position:absolute;color:#fff4c0;font:bold 12px 'DM Mono';text-shadow:1px 2px #5a1715;pointer-events:none;animation:float .75s forwards}
.critical{color:#ffe27a;font-size:15px;text-shadow:1px 2px #681e12,0 0 8px #f6a63c}

