/* Stage 3 character creation and statistics */
.creation-screen,.character-window{position:absolute;z-index:20;inset:0;display:grid;place-items:center;background:rgba(6,11,9,.88);backdrop-filter:blur(4px);pointer-events:auto;padding:16px}.creation-screen.hidden,.character-window.hidden{display:none}.creation-card,.character-card{width:min(920px,96vw);max-height:92vh;overflow:auto;background:linear-gradient(145deg,#28342c,#151e19);border:1px solid rgba(226,194,120,.58);box-shadow:0 12px 50px #050907;padding:clamp(16px,3vw,30px)}.creation-title{font:clamp(25px,4vw,38px) 'IM Fell English SC',serif;color:#f1d48b;text-align:center;margin:0}.creation-subtitle{text-align:center;color:#aaa78f;font-size:10px;letter-spacing:2px;margin:6px 0 20px}.creation-layout{display:grid;grid-template-columns:1fr 1fr;gap:20px}.choice-heading{font:15px 'IM Fell English SC',serif;color:#e8c879;margin:0 0 9px}.choice-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px}.choice-card{border:1px solid rgba(226,194,120,.22);background:rgba(8,15,11,.48);padding:10px;text-align:left;color:#eadfbd;cursor:pointer;min-height:62px;font:11px 'DM Mono',monospace}.choice-card:hover,.choice-card.selected{border-color:#e8c879;background:rgba(130,103,54,.24);box-shadow:inset 0 0 0 1px rgba(232,200,121,.24)}.choice-card b{display:block;color:#f0d58f;margin-bottom:4px;font:15px 'IM Fell English SC',serif}.choice-card small{display:block;color:#aaa78f;font-size:9px;line-height:1.4}.creation-preview{margin-top:13px;border:1px solid rgba(226,194,120,.25);padding:12px;min-height:78px;color:#c9c4a8;font-size:10px;line-height:1.6}.creation-preview strong{color:#e8c879}.creation-name{width:100%;margin-top:12px;border:1px solid var(--line);background:#101813;color:#f3e5bd;padding:11px;font:12px 'DM Mono',monospace}.creation-start{width:100%;border:1px solid #e8c879;background:#685436;color:#fff0c0;padding:13px;margin-top:12px;font:13px 'DM Mono',monospace;letter-spacing:1px;cursor:pointer}.creation-start:hover{background:#806943}.creation-error{min-height:14px;color:#e58b78;text-align:center;font-size:9px;margin-top:6px}.character-card{width:min(620px,96vw)}.character-head{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line);padding-bottom:10px}.character-head h2{font:23px 'IM Fell English SC',serif;color:#f1d48b;margin:0}.character-close{cursor:pointer;color:#e8c879;font-size:24px;padding:4px 10px}.character-summary{color:#c6c1a5;font-size:10px;line-height:1.8;padding:10px 0}.stat-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:6px}.stat-cell{background:rgba(7,13,10,.5);border:1px solid rgba(226,194,120,.16);padding:8px;text-align:center;color:#aaa78f;font-size:8px}.stat-cell b{display:block;color:#f0d58f;font-size:16px;margin-top:5px}.derived-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin-top:8px}.derived-stats div{padding:7px;background:rgba(7,13,10,.4);font-size:9px;color:#c6c1a5}.skill-list{display:grid;grid-template-columns:repeat(2,1fr);gap:6px;margin-top:12px}.skill-entry{border:1px solid rgba(226,194,120,.18);padding:8px;font-size:9px;color:#aaa78f}.skill-entry b{display:block;color:#e8c879;font-size:10px;margin-bottom:4px}.skill-entry.locked{opacity:.45}@media(max-width:620px){.creation-layout{grid-template-columns:1fr;gap:12px}.creation-card{max-height:96vh;padding:14px}.creation-subtitle{margin-bottom:12px}.choice-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.choice-card{padding:8px;min-height:54px}.creation-preview{margin-top:8px}}
