 let toastTimer;function toast(title,sub=''){let el=document.querySelector('#toast');el.innerHTML=title+(sub?`<small>${sub}</small>`:'');el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1350)}

