{min-height:14px;color:#e58b78;text-align:center;font-size:9px;margin-top:6px}.character-card{width:min(620px,96vw)}.character-head{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line);padding-bottom:10px}.character-head h2{font:23px 'IM Fell English SC',serif;color:#f1d48b;margin:0}.character-close{cursor:pointer;color:#e8c879;font-size:24px;padding:4px 10px}.character-summary{color:#c6c1a5;font-size:10px;line-height:1.8;padding:10px 0}.stat-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:6px}.stat-cell{background:rgba(7,13,10,.5);border:1px solid rgba(226,194,120,.16);padding:8px;text-align:center;color:#aaa78f;font-size:8px}.stat-cell b{display:block;color:#f0d58f;font-size:16px;margin-top:5px}.derived-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin-top:8px}.derived-stats div{padding:7px;background:rgba(7,13,10,.4);font-size:9px;color:#c6c1a5}.skill-list{display:grid;grid-template-columns:repeat(2,1fr);gap:6px;margin-top:12px}.skill-entry{border:1px solid rgba(226,194,120,.18);padding:8px;font-size:9px;color:#aaa78f}.skill-entry b{display:block;color:#e8c879;font-size:10px;margin-bottom:4px}.skill-entry.locked{opacity:.45}@media(max-width:620px){.creation-layout{grid-template-columns:1fr;gap:12px}.creation-card{max-height:96vh;padding:14px}.creation-subtitle{margin-bottom:12px}.choice-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.choice-card{padding:8px;min-height:54px}.creation-preview{margin-top:8px}}
