<body>
<canvas id="game" width="780" height="493" style="width: 780px; height: 493px;"></canvas><div class="vignette"></div>
<div class="topbar"><div class="brand">LEGACY OF ETERNIA<small>FIRST LIGHT · PROTOTYPE</small></div><div class="zone">ELDERWIND VILLAGE<span>THE NORTHERN FRONTIER</span></div></div>
<div class="hud">
 <div class="panel status"><div class="portrait-row"><div class="portrait">♜</div><div><div class="hero-name">Kael Ashford</div><div class="level">LEVEL <b id="level">01</b> · HUMAN WARRIOR</div></div></div><div class="meter-label"><span>HP</span><span id="hptext">120 / 120</span></div><div class="meter"><div class="fill hp" id="hpfill" style="width:100%"></div></div><div class="meter-label"><span>MP</span><span id="mptext">45 / 45</span></div><div class="meter"><div class="fill mp" id="mpfill" style="width:100%"></div></div><div class="xpbar"><div class="fill xp" id="xpfill" style="width:0%"></div></div></div>
 <div class="panel target" id="target"><div class="target-name" id="targetname">Wolf</div><div class="meter"><div class="fill hp" id="targethp" style="width:100%"></div></div><div class="target-type" id="targettype">FOREST BEAST · LV. 1</div></div>
 <div class="panel minimap"><canvas id="map" width="108" height="108"></canvas><div class="maplabel">ELDERWIND</div></div>
 <div class="panel quest"><div class="eyebrow">✦ VILLAGE REQUEST</div><h3>Thin the Herd</h3><p>Drive the wolves from the village edge. Defeat <strong id="killcount">0</strong>/3 nearby wolves.</p></div>
 <div class="bottom-left"><div class="joystick" id="joy"><div class="joy-knob" id="knob"></div></div><div class="hint">WASD / ARROWS<br>MOVE · CLICK TO TARGET</div></div>
 <div class="bottom-tools"><div class="tool" id="inventoryBtn">▣ INVENTORY</div><div class="tool" id="charBtn">♙ CHARACTER</div></div>
 <div class="bottom-right"><div class="quick"><div class="slot" title="Health potion"><small>Q</small>🧪<em id="pots">2</em></div><div class="slot" title="Rusty sword"><small>1</small>⚔</div></div><div class="action skill" id="skillBtn">✦<br><small>POWER</small></div><div class="action" id="attackBtn">⚔<br>ATTACK</div></div>
 <div class="toast" id="toast">A sword for a sword</div><div class="panel inventory" id="inventory"><div class="invhead"><span>Adventurer's Pack</span><span class="close" id="closeInv">×</span></div><div class="invgrid" id="invgrid"></div><div class="invnote" id="invnote">A well-traveled pack. Gold: <strong>0</strong><br>Click a nearby drop to collect it.</div></div><div class="screenfade" id="fade"></div><div class="footer">A quiet frontier, before the tales were told</div>
</div>
<div class="creation-screen" id="creationScreen"><section class="creation-card"><h1 class="creation-title">A New Legend Begins</h1><div class="creation-subtitle">CHOOSE YOUR HERITAGE AND PATH</div><div class="creation-layout"><div><h3 class="choice-heading">Race</h3><div class="choice-grid" id="raceChoices"><button class="choice-card selected" data-race="Human"><b>Human</b><small>Balanced attributes · adaptable beginnings</small></button><button class="choice-card" data-race="Elf"><b>Elf</b><small>Swift movement · potent magic · keen senses</small></button><button class="choice-card" data-race="Dark Elf"><b>Dark Elf</b><small>High damage · improved critical chance</small></button><button class="choice-card" data-race="Orc"><b>Orc</b><small>Great strength · sturdy health</small></button><button class="choice-card" data-race="Dwarf"><b>Dwarf</b><small>Strong defense · crafting expertise</small></button></div></div><div><h3 class="choice-heading">Class</h3><div class="choice-grid" id="classChoices"><button class="choice-card selected" data-class="Warrior"><b>Warrior</b><small>Sword fighter · heavy armor · Cleave</small></button><button class="choice-card" data-class="Mage"><b>Mage</b><small>Arcane attacks · powerful spells · mana</small></button><button class="choice-card" data-class="Archer"><b>Archer</b><small>Ranged bow attacks · precision · speed</small></button><button class="choice-card" data-class="Assassin"><b>Assassin</b><small>Fast dagger strikes · critical damage</small></button></div></div></div><div class="creation-preview" id="creationPreview"><strong>Human Warrior</strong><br>Balanced attributes · adaptable beginnings. Sword fighter · heavy armor · Cleave.<br>STR 14 · DEX 11 · INT 10 · CON 13 · WIS 11</div><input id="characterName" class="creation-name" maxlength="18" placeholder="Character name" autocomplete="off"><button id="createCharacter" class="creation-start">ENTER ELDERWIND</button><div class="creation-error" id="creationError"></div></section></div>
<div class="character-window hidden" id="characterWindow"><section class="character-card"><div class="character-head"><h2 id="characterTitle">Character</h2><span class="character-close" id="closeCharacter">×</span></div><div class="character-summary" id="characterSummary"></div><div class="stat-grid" id="statGrid"></div><div class="derived-stats" id="derivedStats"></div><div class="skill-list" id="skillList"></div></section></div>
<script>
(()=>{'use strict';
const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d',{alpha:false}),map=document.querySelector('#map'),mctx=map.getContext('2d');
const W=640,H=360,TILE=32,ISOX=16,ISOY=8,world={w:48,h:48};let scale=1,cam={x:24,y:24},last=0,clock=0,lastSave=0;
function resize(){const d=Math.min(2,window.devicePixelRatio||1);canvas.width=Math.floor(innerWidth*d);canvas.height=Math.floor(innerHeight*d);canvas.style.width=innerWidth+'px';canvas.style.height=innerHeight+'px';scale=d;ctx.imageSmoothingEnabled=false}window.addEventListener('resize',resize);resize();
const races={Human:{stats:{strength:10,dexterity:10,intelligence:10,constitution:10,wisdom:10},tone:'#c9a877',hair:'#5f4b39',accent:'#63806b',trait:'Balanced attributes · adaptable beginnings'},Elf:{stats:{strength:7,dexterity:13,intelligence:12,constitution:8,wisdom:12},tone:'#dfc39a',hair:'#c9b57a',accent:'#527b66',trait:'Swift movement · potent magic · keen senses'},'Dark Elf':{stats:{strength:11,dexterity:13,intelligence:10,constitution:9,wisdom:9},tone:'#9e8ba6',hair:'#29263a',accent:'#70466e',trait:'High damage · improved critical chance'},Orc:{stats:{strength:14,dexterity:8,intelligence:7,constitution:14,wisdom:7},tone:'#829969',hair:'#403b30',accent:'#697b4a',trait:'Great strength · sturdy health'},Dwarf:{stats:{strength:12,dexterity:8,intelligence:9,constitution:13,wisdom:11},tone:'#d0a978',hair:'#8b5237',accent:'#92703e',trait:'Strong defense · crafting expertise'}};
const classes={Warrior:{stats:{strength:4,dexterity:1,intelligence:0,constitution:3,wisdom:1},description:'Sword fighter · heavy armor · Cleave'},Mage:{stats:{strength:0,dexterity:1,intelligence:5,constitution:0,wisdom:4},description:'Arcane attacks · powerful spells · mana'},Archer:{stats:{strength:1,dexterity:5,intelligence:1,constitution:1,wisdom:1},description:'Ranged bow attacks · precision · speed'},Assassin:{stats:{strength:2,dexterity:5,intelligence:1,constitution:0,wisdom:1},description:'Fast dagger strikes · critical damage'}};
const skillCatalog={Warrior:[['Cleave','A sweeping strike that hits nearby foes.',1],['Iron Guard','Passive: reduce incoming damage.',3],['Whirlwind','A stronger spinning area strike.',5],['Battle Focus','Passive: improve critical chance.',8],['Titan Breaker','A devastating heavy blow.',12],['Unyielding','Passive: gain bonus maximum health.',16],['Warlord','Passive: improve attack and defense.',20]],Mage:[['Arcane Bolt','Hurl arcane energy at a distant enemy.',1],['Mana Well','Passive: increase maximum mana.',3],['Frost Nova','Blast nearby foes with frost.',5],['Spellcraft','Passive: improve spell damage.',8],['Meteor','Call a focused burst of flame.',12],['Aether Skin','Passive: resist incoming damage.',16],['Archmage','Passive: greatly improve spell power.',20]],Archer:[['Piercing Shot','Fire a precise arrow at a distant foe.',1],['Sure Aim','Passive: improve critical chance.',3],['Multi-shot','Strike nearby foes with arrows.',5],['Fleetfoot','Passive: move and attack faster.',8],['Deadeye','A powerful long-range shot.',12],['Evasion','Passive: reduce incoming damage.',16],['Master Hunter','Passive: improve all ranged damage.',20]],Assassin:[['Shadow Strike','A swift, critical dagger attack.',1],['Lethality','Passive: improve critical chance.',3],['Fan of Knives','Hit nearby foes in a burst.',5],['Quickstep','Passive: move and attack faster.',8],['Death Mark','A deadly focused strike.',12],['Smoke Veil','Passive: reduce incoming damage.',16],['Nightblade','Passive: greatly improve criticals.',20]]};
function makeAttributes(race,className){const base=races[race].stats,bonus=classes[className].stats;return Object.fromEntries(Object.keys(base).map(k=>[k,base[k]+bonus[k]]))}
let chosenRace='Human',chosenClass='Warrior',savedCharacter=null;
const identity={playerId:crypto.randomUUID(),displayName:'Kael Ashford'};
// Multiplayer seam: a future transport can send intents and feed authoritative snapshots here.
// This prototype deliberately leaves transport disconnected and never fabricates other players.
const network={transport:null,connected:false,snapshotVersion:0,remotePlayers:[],sharedWorld:null,sendCommand(command){if(!this.connected||!this.transport)return false;this.transport.send(JSON.stringify({playerId:identity.playerId,command}));return true},applySnapshot(snapshot){if(!snapshot||snapshot.version<=this.snapshotVersion)return false;this.snapshotVersion=snapshot.version;if(snapshot.player){hero.x=snapshot.player.x;hero.y=snapshot.player.y;hero.hp=snapshot.player.hp;hero.mp=snapshot.player.mp}if(Array.isArray(snapshot.players))this.remotePlayers=snapshot.players;if(snapshot.world)this.sharedWorld=snapshot.world;return true}};
const hero={x:24,y:25,hp:120,maxHp:120,mp:45,maxMp:45,level:1,xp:0,next:100,gold:0,potions:2,dir:0,state:'idle',anim:0,attack:0,atkCd:0,skillCd:0,dead:false,levelFx:0,items:[],race:'Human',className:'Warrior',name:'Kael Ashford',attributes:makeAttributes('Human','Warrior'),equipment:{weapon:{name:'Rusty Sword',icon:'⚔',slot:'weapon',attack:0,defense:0}}};
let mobs=[],drops=[],target=null,kills=0,inventoryOpen=false;
const SAVE_KEY='legacyOfEternia.character.v1';
function saveGame(){try{const data={version:1,name:hero.name,race:hero.race,className:hero.className,attributes:hero.attributes,level:hero.level,xp:hero.xp,next:hero.next,gold:hero.gold,potions:hero.potions,hp:hero.hp,maxHp:hero.maxHp,mp:hero.mp,maxMp:hero.maxMp,x:hero.x,y:hero.y,kills,equipment:hero.equipment,items:hero.items};localStorage.setItem(SAVE_KEY,JSON.stringify(data))}catch(e){}}
function loadGame(){try{const raw=localStorage.getItem(SAVE_KEY);if(!raw)return null;const data=JSON.parse(raw);if(!data||data.version!==1||!races[data.race]||!classes[data.className]||typeof data.name!=='string')return null;return data}catch(e){return null}}
function applySaved(data){hero.name=data.name.slice(0,18)||'Adventurer';hero.race=data.race;hero.className=data.className;hero.attributes=makeAttributes(data.race,data.className);hero.level=Math.max(1,Math.min(20,Number(data.level)||1));hero.xp=Math.max(0,Number(data.xp)||0);hero.next=Math.max(100,Number(data.next)||100);hero.gold=Math.max(0,Number(data.gold)||0);hero.potions=Math.max(0,Number(data.potions)||0);hero.maxHp=Math.max(1,Number(data.maxHp)||75+hero.attributes.constitution*3+(hero.level-1)*18);hero.hp=Math.min(hero.maxHp,Math.max(1,Number(data.hp)||hero.maxHp));hero.maxMp=Math.max(1,Number(data.maxMp)||25+hero.attributes.intelligence*2+hero.attributes.wisdom+(hero.level-1)*8);hero.mp=Math.min(hero.maxMp,Math.max(0,Number(data.mp)||hero.maxMp));hero.x=Math.max(2,Math.min(46,Number(data.x)||24));hero.y=Math.max(2,Math.min(46,Number(data.y)||25));hero.equipment=data.equipment&&data.equipment.weapon?data.equipment:{weapon:{name:'Rusty Sword',icon:'⚔',slot:'weapon',attack:0,defense:0}};hero.items=Array.isArray(data.items)?data.items.slice(0,24):[];kills=Math.max(0,Number(data.kills)||0);identity.displayName=hero.name}
function renderChoices(){document.querySelector('#raceChoices').innerHTML=Object.entries(races).map(([name,r])=>`<button class="choice-card${name===chosenRace?' selected':''}" data-race="${name}"><b>${name}</b><small>${r.trait}</small></button>`).join('');document.querySelector('#classChoices').innerHTML=Object.entries(classes).map(([name,c])=>`<button class="choice-card${name===chosenClass?' selected':''}" data-class="${name}"><b>${name}</b><small>${c.description}</small></button>`).join('');document.querySelectorAll('[data-race]').forEach(b=>b.onclick=()=>{chosenRace=b.dataset.race;renderChoices()});document.querySelectorAll('[data-class]').forEach(b=>b.onclick=()=>{chosenClass=b.dataset.class;renderChoices()});const attrs=makeAttributes(chosenRace,chosenClass);document.querySelector('#creationPreview').innerHTML=`<strong>${chosenRace} ${chosenClass}</strong><br>${races[chosenRace].trait}. ${classes[chosenClass].description}.<br>STR ${attrs.strength} · DEX ${attrs.dexterity} · INT ${attrs.intelligence} · CON ${attrs.constitution} · WIS ${attrs.wisdom}`}
function createCharacter(){const name=document.querySelector('#characterName').value.trim();if(name.length<2){document.querySelector('#creationError').textContent='Enter a name with at least 2 characters.';return}hero.name=name.slice(0,18);hero.race=chosenRace;hero.className=chosenClass;hero.attributes=makeAttributes(chosenRace,chosenClass);hero.maxHp=75+hero.attributes.constitution*3;hero.hp=hero.maxHp;hero.maxMp=25+hero.attributes.intelligence*2+hero.attributes.wisdom;hero.mp=hero.maxMp;identity.displayName=hero.name;document.querySelector('#creationScreen').classList.add('hidden');document.querySelector('#creationError').textContent='';syncCharacter();syncHud();saveGame();toast(`Welcome, ${hero.name}`,`${hero.race} ${hero.className} · Level 1`)}
